async fn spawn_debug_sandbox_child(
    program: PathBuf,
    args: Vec<String>,
    arg0: Option<&str>,
    cwd: PathBuf,
    network_sandbox_policy: NetworkSandboxPolicy,
    mut env: std::collections::HashMap<String, String>,
    apply_env: impl FnOnce(&mut std::collections::HashMap<String, String>),
) -> std::io::Result<Child> {
    let mut cmd = TokioCommand::new(&program);
    #[cfg(unix)]
    cmd.arg0(arg0.map_or_else(|| program.to_string_lossy().to_string(), String::from));
    #[cfg(not(unix))]
    let _ = arg0;
    cmd.args(args);
    cmd.current_dir(cwd);
    apply_env(&mut env);
    cmd.env_clear();
    cmd.envs(env);

    if !network_sandbox_policy.is_enabled() {
        cmd.env(CODEX_SANDBOX_NETWORK_DISABLED_ENV_VAR, "1");
    }

    cmd.stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .kill_on_drop(true)

pub fn create_env(
    policy: &ShellEnvironmentPolicy,
    thread_id: Option<ThreadId>,
) -> HashMap<String, String> {
    let thread_id = thread_id.map(|thread_id| thread_id.to_string());
    shell_environment::create_env(policy, thread_id.as_deref())
}

// `inherit` strategy.
let mut env_map: HashMap<String, String> = match policy.inherit {
    ShellEnvironmentPolicyInherit::All => vars.into_iter().collect(),
    ShellEnvironmentPolicyInherit::None => HashMap::new(),
    ShellEnvironmentPolicyInherit::Core => {
        #[cfg(not(target_os = "windows"))]
        let core_env_vars = UNIX_CORE_ENV_VARS;

    env_map.retain(|k, _| !matches_any(k, &policy.exclude));
}

// Step 4 - Apply user-provided overrides.
for (key, val) in &policy.r#set {
    #[cfg(windows)]
    env_map.retain(|existing, _| !existing.eq_ignore_ascii_case(key));
    env_map.insert(key.clone(), val.clone());
}

// Step 5 - If include_only is non-empty, keep only the matching vars.
if !policy.include_only.is_empty() {
    env_map.retain(|k, _| matches_any(k, &policy.include_only));
}

// Step 6 - Populate the thread ID environment variable when provided.
if let Some(thread_id) = thread_id {
    env_map.insert(CODEX_THREAD_ID_ENV_VAR.to_string(), thread_id.to_string());
}

// Restricted launch context cannot be restored through user-provided shell
// environment overrides.
env_map.retain(|name, _| !is_non_inheritable_env_var(name));

env_map

/// `docs/linux_sandbox.md` for the Linux semantics.
pub fn create_linux_sandbox_command_args_for_permission_profile(
    command: Vec<String>,
    command_cwd: &Path,
    permission_profile: &PermissionProfile,
    sandbox_policy_cwd: &Path,
    use_legacy_landlock: bool,
    managed_network: Option<&ManagedNetworkSandboxContext>,
) -> Vec<String> {
    let permission_profile_json = serde_json::to_string(permission_profile)
        .unwrap_or_else(|err| panic!("failed to serialize permission profile: {err}"));
    let sandbox_policy_cwd = sandbox_policy_cwd
        .to_str()
        .unwrap_or_else(|| panic!("cwd must be valid UTF-8"))
        .to_string();
    let command_cwd = command_cwd
        .to_str()
        .unwrap_or_else(|| panic!("command cwd must be valid UTF-8"))
        .to_string();

    let mut linux_cmd: Vec<String> = vec![
        "--sandbox-policy-cwd".to_string(),
        sandbox_policy_cwd,
        "--command-cwd".to_string(),
        command_cwd,
        "--permission-profile".to_string(),
        permission_profile_json,
    ];
    // Proxy-only networking requires bubblewrap's isolated network namespace.
    if use_legacy_landlock && managed_network.is_none() {
        linux_cmd.push("--use-legacy-landlock".to_string());
    }
    if let Some(managed_network) = managed_network {
        linux_cmd.push("--managed-network".to_string());
        linux_cmd.push(
            serde_json::to_string(managed_network)
                .unwrap_or_else(|err| panic!("failed to serialize managed network context: {err}")),
        );
    }
    linux_cmd.push("--".to_string());
    linux_cmd.extend(command);
    linux_cmd
}

